{"content": """"Test that FieldABC and SchemaABC are true abstract base classes.

Attempting to instantiate a subclass that does not implement all abstract
methods should raise TypeError. Also verify that proper subclasses work.
"""
import pytest
from marshmallow.base import FieldABC, SchemaABC


class IncompleteField(FieldABC):
    pass


class IncompleteSchema(SchemaABC):
    pass


class CompleteField(FieldABC):
    def serialize(self, attr, obj, accessor=None):
        return "serialized"

    def deserialize(self, value):
        return "deserialized"

    def _serialize(self, value, attr, obj, **kwargs):
        return "serialized_internal"

    def _deserialize(self, value, attr, data, **kwargs):
        return "deserialized_internal"


class CompleteSchema(SchemaABC):
    def dump(self, obj, *, many=None):
        return {"dumped": True}

    def dumps(self, obj, *, many=None):
        return '{"dumped": true}'

    def load(self, data, *, many=None, partial=None, unknown=None):
        return {"loaded": True}

    def loads(self, json_data, *, many=None, partial=None, unknown=None, **kwargs):
        return {"loaded": True}


class TestFieldABC:
    def test_cannot_instantiate_without_implementing_abstract_methods(self):
        with pytest.raises(TypeError):
            IncompleteField()

    def test_can_instantiate_with_all_abstract_methods_implemented(self):
        field = CompleteField()
        assert field.serialize("attr", {"attr": "val"}) == "serialized"
        assert field.deserialize("val") == "deserialized"
        assert field._serialize("val", "attr", {}) == "serialized_internal"
        assert field._deserialize("val", "attr", {}) == "deserialized_internal"


class TestSchemaABC:
    def test_cannot_instantiate_without_implementing_abstract_methods(self):
        with pytest.raises(TypeError):
            IncompleteSchema()

    def test_can_instantiate_with_all_abstract_methods_implemented(self):
        schema = CompleteSchema()
        assert schema.dump({"a": 1}) == {"dumped": True}
        assert schema.dumps({"a": 1}) == '{"dumped": true}'
        assert schema.load({"a": 1}) == {"loaded": True}
        assert schema.loads('{"a": 1}') == {"loaded": True}", "path": "tests/test_base_abc.py"}
